def solve():
    n = int(input())

    # Build friendship graph
    friends = [[] for _ in range(n + 1)]
    for _ in range(int(input())):
        u, v = map(int, input().split())
        friends[u].append(v)
        friends[v].append(u)

    # Build dislike graph
    dislikes = [[] for _ in range(n + 1)]
    for _ in range(int(input())):
        u, v = map(int, input().split())
        dislikes[u].append(v)
        dislikes[v].append(u)

    # Find connected components in the friendship graph
    visited = [False] * (n + 1)
    max_size = 0

    for start in range(1, n + 1):
        if not visited[start]:
            # BFS to find connected component
            queue = [start]
            visited[start] = True
            component = [start]

            while queue:
                node = queue.pop(0)
                for neighbor in friends[node]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        component.append(neighbor)
                        queue.append(neighbor)

            # Check if this component is valid (no dislikes within)
            valid = True
            for i in range(len(component)):
                for j in range(i + 1, len(component)):
                    if component[j] in dislikes[component[i]]:
                        valid = False
                        break
                if not valid:
                    break

            if valid:
                max_size = max(max_size, len(component))

    print(max_size)

solve()
