def count_secret_message(s):
    n = len(s)

    # dp[len][start][diff] = number of ways to form a hidden string of length 'len'
    # starting at position 'start' with common difference 'diff'
    dp = [[dict() for _ in range(n)] for _ in range(n + 1)]

    # Base case: length 1
    for i in range(n):
        dp[1][i] = {0: 1}  # diff doesn't matter for length 1, just count 1 way

    # For lengths 2 to n
    for length in range(2, n + 1):
        for start in range(n):
            for diff in range(1, n - start):
                # We can extend a hidden string of length-1 starting at start+diff with diff
                if start + diff < n and (start + diff) in dp[length - 1]:
                    dp[length][start][diff] = dp[length - 1][start + diff].get(diff, 0)

    # Find the maximum count
    max_count = 0
    for len in range(1, n + 1):
        for start in range(n):
            if len in dp[start]:
                for diff in dp[start][len]:
                    max_count = max(max_count, dp[start][len][diff])

    return max_count

s = input().strip()
print(count_secret_message(s))
