    # Count numbers with exactly k bits set in [mid+1, 2*mid]
    count = count_k_bits_set(mid + 1, 2 * mid, k)

    if count == m:
        answer = mid
        break
    elif count < m:
        # Need to decrease m, so decrease n
        high = mid - 1
    else:
        # Need to increase m, so increase n
        low = mid + 1

