def is_prime(n):
    """Check if n is prime"""
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, isqrt(n) + 1, 2):
        if n % i == 0:
            return False
    return True

def count_valid(L, R):
    """Count numbers x in [L, R] that are NOT prime"""
    if R < 2:
        return 0
    if L < 2:
        L = 2
    # Count non-prime numbers
    # Total numbers = R - L + 1
    # Primes in range [L, R]
    count = R - L + 1
    # Subtract primes
    count -= count_primes_in_range(L, R)
    return count

