import sys
from collections import defaultdict

# Precompute smallest prime factors up to 100000
def build_spf(max_n):
    spf = list(range(max_n + 1))
    for i in range(2, int(max_n ** 0.5) + 1):
        if spf[i] == i:  # i is prime
            for j in range(i * i, max_n + 1, i):
                if spf[j] == j:
                    spf[j] = i
    return spf

spf = build_spf(100000)

def factor(n):
    factors = {}
    if n == 1:
        return factors
    while n != 1:
        p = spf[n]
        cnt = 0
        while n % p == 0:
            n //= p
            cnt += 1
        factors[p] = cnt
    return factors

def compute_signature(factors, k):
    sig = []
    for p, e in factors.items():
        rem = e % k
        if rem > 0:
            sig.append((p, rem))
    sig.sort()
    return tuple(sig)

def compute_complement(sig, k):
    comp = []
    for p, e in sig:
        new_e = k - e
        if new_e > 0:
            comp.append((p, new_e))
    comp.sort()
    return tuple(comp)

def solve() -> None:
    data = sys.stdin.read().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    k = int(next(it))
    a = [int(next(it)) for _ in range(n)]

    counts = defaultdict(int)
    for num in a:
        factors = factor(num)
        sig = compute_signature(factors, k)
        counts[sig] += 1

    zero_count = counts.get(tuple(), 0)
    del counts[tuple()]  # remove empty signature

    total = zero_count * (zero_count - 1) // 2

    # Process non-zero signatures
    keys = list(counts.keys())
    visited = set()
    for sig in keys:
        if sig in visited:
            continue
        cnt = counts[sig]
        comp = compute_complement(sig, k)
        if comp not in counts:
            visited.add(sig)
            continue
        if comp == sig:
            # self-complement
            total += cnt * (cnt - 1) // 2
        else:
            # distinct
            total += cnt * counts[comp]
        visited.add(sig)
        visited.add(comp)

    print(total)

if __name__ == "__main__":
    solve()
