def solve():
    import sys
    input = sys.stdin.read
    x2 = int(input().strip())

    # Find all primes up to x2 using Sieve of Eratosthenes
    def sieve(limit):
        is_prime = [True] * (limit + 1)
        is_prime[0] = is_prime[1] = False
        for i in range(2, int(limit ** 0.5) + 1):
            if is_prime[i]:
                for j in range(i * i, limit + 1, i):
                    is_prime[j] = False
        primes = [i for i, val in enumerate(is_prime) if val]
        return primes

    primes = sieve(x2 * 2)  # Double the limit to be safe

    min_x0 = x2  # Start with maximum possible value

    # For each possible X1 that could lead to x2
    for x1 in range(3, x2 + 1):
        for p in primes:
            if p >= x1:
                break
            if x2 % p == 0:
                # Check if x1 could lead to x2 in one move
                # For x1 → x2 with prime p
                # We need ceiling(x1/p) * p = x2
                # Since x1 <= x2 and x1 < p is not possible
                # x1 could be x2 itself if p divides x1 and x1 = x2
                if x1 == x2 and x2 % p == 0:
                    # x2 itself is a predecessor if p divides x2
                    # Now find all X0 that could lead to x1 = x2
                    for x0 in range(3, x1 + 1):
                        for q in primes:
                            if q >= x0:
                                break
                            if x1 % q == 0:
                                min_x0 = min(min_x0, x0)
                                break
                else:
                    # x1 could be x2 - p or something else
                    # Actually, x1 must be in [x2 - p, x2]
                    # And x1 must be <= p (since p < x1 is not possible if p > x1)
                    # Wait, p < x1 means x1 > p, but p < x2 as well
                    if p < x1:
                        # x1 could be any value such that ceiling(x1/p)*p = x2
                        # And p < x1
                        if x2 - x1 >= 0:
                            # x1 could be x2 - p, x2 - 2p, ... but also x1 could be x2 itself
                            # Actually, if x1 > p, then p < x1 is true
                            if x1 == x2:
                                # x2 itself is a predecessor
                                for x0 in range(3, x1 + 1):
                                    for q in primes:
                                        if q >= x0:
                                            break
                                        if x1 % q == 0:
                                            min_x0 = min(min_x0, x0)
                                            break
                            else:
                                # x1 could be x2 - p
                                if x1 == x2 - p:
                                    for x0 in range(3, x1 + 1):
                                        for q in primes:
                                            if q >= x0:
                                                break
                                            if x1 % q == 0:
                                                min_x0 = min(min_x0, x0)
                                                break

    return min_x0

