import sys

# Read input
def readints():
    return list(map(int, sys.stdin.readline().split()))

# Solve the problem
def solve():
    # Read n, m, k
    n, m, k = readints()

    # Read government nodes
    gov = set()
    gov_line = sys.stdin.readline().split()
    for gov_node in gov_line:
        gov.add(int(gov_node))

    # Build adjacency list
    adj = {}
    for _ in range(m):
        u, v = map(int, sys.stdin.readline().split())
        if u not in adj:
            adj[u] = []
        if v not in adj:
            adj[v] = []
        adj[u].append(v)
        adj[v].append(u)

    # Find connected components (regardless of government status)
    visited = set()
    components = []

    for node in range(1, n + 1):
        if node not in visited:
            q = [node]
            visited.add(node)
            comp = [node]

            while q:
                current = q.pop(0)
                for neighbor in adj[current]:
                    if neighbor not in visited:
                        visited.add(neighbor)
                        comp.append(neighbor)
                        q.append(neighbor)

            components.append(comp)

    # Now calculate max edges
    total_max_edges = 0
    for comp in components:
        s = len(comp)
        total_max_edges += s * (s - 1) // 2

    # Subtract current edges
    total_max_edges -= m

    print(total_max_edges)

