def count_distinct_numbers(a):
    if not a:
        return 0

    # dp[i] is a dictionary: key = number of 9's, value = set of strings
    # representing distinct numbers with that many 9's
    dp = [{} for _ in range(len(a) + 1)]
    dp[0][0] = {""}

    for i in range(1, len(a) + 1):
        # Keep the i-th digit as is
        for count, strings in dp[i-1].items():
            for s in strings:
                next_count = count
                if a[i-1] == '9':
                    next_count += 1
                dp[i][next_count] = dp[i].get(next_count, set()) | {s + a[i-1]}

        # Merge i-1 and i if they sum to 9
        if i >= 2 and int(a[i-2]) + int(a[i-1]) == 9:
            for count, strings in dp[i-2].items():
                for s in strings:
                    next_count = count
                    if '9' == '9':
                        next_count += 1
                    dp[i][next_count] = dp[i].get(next_count, set()) | {s + '9'}

    # Find the maximum number of 9's
    max_9s = max(dp[len(a)].keys())

    # Count distinct numbers with max 9's
    return len(dp[len(a)][max_9s])

