def can_measure(d, marks):
    """Check if distance d can be measured with the given marks"""
    n = len(marks)
    for i in range(n):
        for j in range(i+1, n):
            if marks[j] - marks[i] == d:
                return True
    return False

n, l, x, y = map(int, input().split())
marks = list(map(int, input().split()))

# Check if we can already measure both x and y
if can_measure(x, marks) and can_measure(y, marks):
    print(0)
    print()
else:
    # Check if we can measure one of them
    can_x = can_measure(x, marks)
    can_y = can_measure(y, marks)

    # If we can measure only one
    if (can_x and not can_y) or (can_y and not can_x):
        # Try adding just the missing distance
        missing = x if can_y else y
        print(1)
        print(missing)
    else:
        # We can measure neither x nor y
        # Try adding x, y, or x+y (if x+y <= l)
        added = []

        # Try adding x
        if not can_measure(x, marks + [x]):
            added.append(x)

        # Try adding y
        if not can_measure(y, marks + [y]):
            added.append(y)

        # Try adding x+y if possible
        if not can_measure(x, marks + [x]) and not can_measure(y, marks + [y]):
            if x + y <= l:
                added.append(x + y)
                added.append(x)
                added.append(y)
            else:
                # We need to add both x and y
                added.append(x)
                added.append(y)

        # If we still can't measure both after adding x and y
        if len(added) == 0:
            # Try adding x
            added.append(x)
        elif len(added) == 1:
            # Try adding y
            if not can_measure(y, marks + added + [y]):
                added.append(y)
        elif len(added) == 2:
            # Already added x and y
            pass

        print(len(added))
