def solve():
    n, m = map(int, input().split())
    grid = []
    for _ in range(n):
        row = list(map(int, input().split()))
        grid.append(row)

    # Find all possible k values
    possible_ks = set()
    max_k = 0

    # Find the maximum possible k
    for i in range(n):
        for j in range(m):
            left = j - 1
            right = m - 1 - j
            up = i - 1
            down = n - 1 - i
            max_k_pos = min(left, right, up, down)
            max_k = max(max_k, max_k_pos)

    # Check all k values from 2 to max_k
    for k in range(2, max_k + 1):
        # Check if all positions that should be 1 are indeed 1
        valid = True
        for i in range(n):
            for j in range(m):
                # Check if (i, j) should be 1
                # For this k, the position (i, j) is 1 if:
                # 1. Dima was staying in the square (i, j)
                # 2. Dima was flying above it
                #
                # To be flying above it, Dima must have passed through
                # this square during a kick

                # Check if it's a corner: (i, j) is a corner if it's at
                # max distance in all four directions
                if (j == 0 or j == m - 1) and (i == 0 or i == n - 1):
                    # Corner squares can only be 1 if k divides max distance in all four directions
                    dist = min(j, m - 1 - j, i, n - 1 - i)
                    if dist % k == 0:
                        # It's a corner and should be 1 if distance is a multiple of k
                        if grid[i][j] == 0:
                            valid = False
                    else:
                        # It's a corner but distance isn't a multiple of k
                        if grid[i][j] == 1:
                            valid = False
                else:
                    # Edge squares (but not corner)
                    dist = min(j, m - 1 - j, i, n - 1 - i)
                    if dist % k == 0:
                        # It's an edge and should be 1 if distance is a multiple of k
                        if grid[i][j] == 0:
                            valid = False
                    else:
                        # It's an edge but distance isn't a multiple of k
                        if grid[i][j] == 1:
                            valid = False

        if valid:
            possible_ks.add(k)

    if possible_ks:
        possible_ks = sorted(possible_ks)
        print(' '.join(map(str, possible_ks)))
    else:
        print(-1)

