        dp = [[0] * (n + 1) for _ in range(k + 1)]

        # Base case: remove 1 element
        for i in range(1, n + 1):
            # Check if we can remove element i first
            # It must be adjacent to an element in b
            if len(adj[i]) > 0 and len(adj[i] & b_set) > 0:
                dp[1][i] = 1

        # DP transition
        for i in range(1, k):
            for last_removed in range(1, n + 1):
                if dp[i][last_removed] == 0:
                    continue

                # Try removing any other element
                for candidate in range(1, n + 1):
                    if candidate == last_removed:
                        continue

                    # Check if we can remove candidate next
                    # It must be adjacent to the last removed element
                    if candidate in adj[last_removed]:
                        dp[i + 1][candidate] = (dp[i + 1][candidate] + dp[i][last_removed]) % MOD

        # Answer is the sum of all dp[k][*]
        result = sum(dp[k][i] for i in range(1, n + 1)) % MOD
        print(result)

