            data += input().split()
        a = list(map(int, data[:k]))

        # Read m-1 observations
        observations = []
        for _ in range(m - 1):
            # Skip empty lines
            while True:
                if not input().strip():
                    continue
                break

            data = input().split()
            while len(data) < 2:
                data += input().split()
            tj, rj = int(data[0]), int(data[1])
            observations.append((tj, rj))

        answer = []
        for i in range(k):
            could_run_out = True

            for tj, rj in observations:
                if tj == i + 1 and rj == 0:
                    # Passenger got dish i when it was available
                    # This doesn't force it to run out
                    pass
                elif tj == i + 1 and rj == 1:
                    # Passenger was disappointed after asking for dish i
                    # This means dish i was already used up
                    could_run_out = False
                elif tj == 0 and rj == 1:
                    # Passenger was disappointed but we don't know what dish they asked for
                    # This means some dish was not available
                    could_run_out = False

            usage_count = sum(1 for tj, rj in observations if tj == i + 1 and rj == 0)
            if usage_count > a[i]:
                could_run_out = False

            answer.append('Y' if could_run_out else 'N')

        print(''.join(answer))

