    n = int(sys.stdin.readline())
    bombs = []
    for _ in range(n):
        x, y = map(int, sys.stdin.readline().split())
        bombs.append((x, y))

    # Group bombs by rows and columns
    row_bombs = []
    col_bombs = []

    # Find all bombs on positive x-axis (y=0)
    for x, y in bombs:
        if y == 0 and x > 0:
            row_bombs.append(x)

    # Find all bombs on positive y-axis (x=0)
    for x, y in bombs:
        if x == 0 and y > 0:
            col_bombs.append(y)

    # Sort by distance from origin
    row_bombs.sort()
    col_bombs.sort()

    # Move to and from positive x-axis bombs
    if row_bombs:
        farthest_right = row_bombs[-1]
        print(f"1 {farthest_right} R")
