def find_rank(n, permutation):
    rank = 0
    used = [False] * n
    fact = [1] * n

    for i in range(1, n):
        fact[i] = fact[i-1] * i

    for i in range(n):
        smaller = 0
        for j in range(n):
            if not used[j] and permutation[i] > j:
                smaller += 1

        rank += smaller * fact[n - i - 1]
        used[permutation[i]] = True

    return rank

def find_permutation(n, rank):
    permutation = [0] * n
    used = [False] * n
    fact = [1] * n

    for i in range(1, n):
        fact[i] = fact[i-1] * i

    for i in range(n):
        for j in range(n):
            if not used[j]:
                # This is the correct number for position i
                if rank >= fact[n - i - 1]:
                    # This prefix is too small, skip it
                    rank -= fact[n - i - 1]
                else:
                    # This is the prefix we want
                    permutation[i] = j
                    used[j] = True
                    break

    return permutation

n = int(input())
perm_p = list(map(int, input().split()))
perm_q = list(map(int, input().split()))

rank_p = find_rank(n, perm_p)
rank_q = find_rank(n, perm_q)

target_rank = (rank_p + rank_q) % (n * (n - 1) * (n - 2) * (n - 3)) if n > 3 else 0

result = find_permutation(n, target_rank)

print(' '.join(map(str, result)))
