{"code": "import sys

def solve():
    n, p, t = sys.stdin.read().split()
    n = int(n)
    p = float(p)
    t = int(t)

    # dp[s][t] = expected number of people on escalator after t seconds when s people have entered
    # We'll use a 2D array, but we can optimize by only keeping two rows
    dp = [[0.0] * (t + 1) for _ in range(n + 1)]

    # Base case: after 0 seconds, s people have entered
    for s in range(n + 1):
        dp[s][0] = float(s)

    for time in range(1, t + 1):
        for s in range(n, -1, -1):
            # Transition: with probability p, s+1 people have entered
            if s + 1 <= n:
                dp[s][time] = p * dp[s+1][time-1]
            # With probability 1-p, s people remain
            dp[s][time] += (1 - p) * dp[s][time-1]

    print("%.12f" % dp[0][t])

if __name__ == "__main__":
    solve()
"}

