def solve():
    X2 = int(input())

    # Find primes using sieve
    def sieve(n):
        is_prime = [True] * (n + 1)
        is_prime[0] = is_prime[1] = False
        for i in range(2, int(n**0.5) + 1):
            if is_prime[i]:
                for j in range(i*i, n + 1, i):
                    is_prime[j] = False
        return [i for i, val in enumerate(is_prime) if val]

    primes = sieve(X2 + 1)

    # Find all possible predecessors of a number
    def get_predecessors(n):
        res = []
        for p in primes:
            if p >= n:
                break
            if n % p == 0:
                k = n // p
                # Previous number could be any from p+1 to k*p
                for pred in range(p + 1, k * p + 1):
                    res.append(pred)
        return res

    # Use BFS to find minimum starting value
    from collections import deque

    visited = set()
    queue = deque([(X2, 2)])  # (current number, number of turns taken)

    min_start = None

    while queue:
        num, turns = queue.popleft()

        if turns == 0:
            min_start = min(min_start, num)
            continue

        # Find all predecessors
        predecessors = get_predecessors(num)

        for pred in predecessors:
            if pred not in visited:
                visited.add(pred)
                queue.append((pred, turns - 1))

    print(min_start)

solve()
