import sys
from collections import defaultdict

def count_pairs(n, k, numbers):
    """Count pairs i < j such that a_i * a_j is a perfect k-th power"""

    # Function to factorize a number into primes and return exponents modulo k
    def factorize(num):
        if num == 1:
            return {}

        prime_factors = defaultdict(int)

        # Check for factor 2
        while num % 2 == 0:
            prime_factors[2] += 1
            num //= 2

        # Check for odd factors
        factor = 3
        while factor * factor <= num:
            while num % factor == 0:
                prime_factors[factor] += 1
                num //= factor
            factor += 2

        if num > 1:
            prime_factors[num] += 1

        # Take exponents modulo k and store
        return {p: e % k for p, e in prime_factors.items()}

    # Count how many numbers have each signature
    signature_count = defaultdict(int)

    for num in numbers:
        signature = factorize(num)
        signature_count[signature] += 1

    # Count pairs where signatures are complementary
    pairs = 0

    # For each signature, find its complement
    seen = set()

    for signature, count in signature_count.items():
        if signature in seen:
            continue

        # Compute complement: for each prime, e -> (k - e) % k
        complement = {}
        for prime, exponent in signature.items():
            complement[prime] = (k - exponent) % k

        # Add the complement to seen and update pairs
        seen.add(signature)
        seen.add(complement)

        # If the complement is present, add pairs
        if complement in signature_count:
            pairs += count * signature_count[complement]

    return pairs

if __name__ == "__main__":
    input = sys.stdin.read().split()
    if not input:
        print(0)
        sys.exit(0)

    n = int(input[0])
    k = int(input[1])
    numbers = list(map(int, input[2:2+n]))

    result = count_pairs(n, k, numbers)
    print(result)
