import sys

def count_set_bits(x):
    """Count the number of bits set in x"""
    count = 0
    while x > 0:
        if x & 1:
            count += 1
        x >>= 1
    return count

def solve(s, x):
    if s - x < 0 or (s - x) % 2 != 0:
        return 0
    a_and_b = (s - x) // 2

    # Check if both a and b can be positive
    # If a_and_b == 0, then a and b have no common bits
    if a_and_b == 0:
        # a = 2^i, b = 2^j (distinct powers of 2)
        # x = a ^ b = a + b = s
        # For each bit set in x, we choose which number gets that bit
        # But we can't choose the same bit for both
        k = count_set_bits(x)
        if k >= 2:
            return 2 ** (k - 1)
        else:
            return 0
    else:
        # a_and_b > 0 means both a and b share at least one bit
        # So neither can be 0
        # For each bit where x is set, we can independently choose which number gets that bit
        k = count_set_bits(x)
        return 2 ** k

s, x = map(int, sys.stdin.read().split())
