        if 2 * j > n:
            break  # k must be <= n, so 2j <= n + k, but k > j, so 2j < i + k + 1 <= 2n + 1
        for k in range(j + 1, n + 1):
            if 2 * j == i + k:  # Check if indices form arithmetic progression
                three_counts[ord(s[i]) - ord('a'), ord(s[j]) - ord('a'), ord(s[k]) - ord('a')] += 1

