    u, v = map(int, input().split())
    if u not in dislikes:
        dislikes[u] = set()
    if v not in dislikes:
        dislikes[v] = set()
    dislikes[u].add(v)
    dislikes[v].add(u)

# Find connected components in friendship graph
visited = set()
components = []

for person in friends:
    if person not in visited:
        # DFS to find component
        stack = [person]
        visited.add(person)
        component = set()
        component.add(person)

        while stack:
            current = stack.pop()
            for neighbor in friends[current]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    component.add(neighbor)
                    stack.append(neighbor)

        components.append(component)

# Check if any component has dislikes within it
