def is_beautiful(num):
    num_str = str(num)
    count_1 = num_str.count('1')
    return count_1 <= 1 and all(c in '01' for c in num_str)

n = int(input())
nums = list(map(int, input().split()))

# Check if there's a zero in the beautiful numbers
has_zero = False
non_beautiful = None
beautiful_product = 1

for num in nums:
    if not is_beautiful(num):
        non_beautiful = num
    else:
        if num == 0:
            has_zero = True
        else:
            num_str = str(num)
            if num_str[0] == '1':
                power = len(num_str) - 1
                beautiful_product *= 10 ** power

