import sys

def is_beautiful(s):
    """Check if a string is a beautiful number"""
    ones = s.count('1')
    if ones > 1:
        return False
    return all(c in '01' for c in s)

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    numbers = data[1:n+1]

    product = 1
    total_exponent = 0

    for num in numbers:
        s = num
        if s == '0':
            # If 0 is present, product is 0
            product = 0
        elif is_beautiful(s):
            # Count the exponent: length - 1
            exponent = len(s) - 1
            total_exponent += exponent
        else:
            # Multiply the number directly
            product *= int(s)

    # Combine result
    if product == 0:
        print(0)
    else:
        # The product is (product of non-beautiful numbers) * 10^total_exponent
        # Convert to string and add trailing zeros
        print(str(product) + '0' * total_exponent)

if __name__ == "__main__":
    solve()
"}

