def solve():
    n, s, l = map(int, input().split())
    a = list(map(int, input().split()))

    # dp[i] = minimum number of pieces to split first i numbers
    dp = [float('inf')] * (n + 1)
    dp[0] = 0

    for i in range(1, n + 1):
        # Try to end a piece at position i
        # We need to find j such that i-j >= l and max-min <= s
        # Start at 0, not i-l
        for j in range(0, i):
            if i - j >= l:
                piece = a[j:i]
                if max(piece) - min(piece) <= s:
                    dp[i] = min(dp[i], dp[j] + 1)

    result = dp[n]
    print(result if result != float('inf') else -1)

solve()
