def count_k_ones(x, k):
    """Count numbers from 1 to x with exactly k bits set."""
    if k < 1:
        return 1  # Only 0 has 0 ones, but we exclude 0 for range [n+1, 2n]
    if k > x.bit_length():
        return 0
    # DP over bits: dp[pos][cnt][tight] = count
    # pos: current bit position (0=LSB)
    # cnt: number of bits set so far
    # tight: whether we're tight to the prefix of x
    # memoize
    from functools import lru_cache

    bits = [int(bit) for bit in bin(x)[2:]]
    n_bits = len(bits)

    @lru_cache(maxsize=None)
    def dp(pos, cnt, tight):
        if cnt > k:
            return 0
        if pos == n_bits:
            return 1 if cnt == k else 0

        limit = bits[pos] if tight else 1
        total = 0
        for b in range(limit + 1):
            new_tight = tight and (b == limit)
            if b == 1:
                new_cnt = cnt + 1
            else:
                new_cnt = cnt
            total += dp(pos + 1, new_cnt, new_tight)
        return total

    return dp(0, 0, True)

# Binary search
m, k = map(int, input().split())
low = 1
high = 10**18
result = None

while low <= high:
    mid = (low + high) // 2
    # Count numbers in [mid+1, 2*mid] with exactly k ones
    count = count_k_ones(2 * mid, k) - count_k_ones(mid, k)

    if count == m:
        result = mid
        break
    elif count < m:
        low = mid + 1
    else:
        high = mid - 1

print(result)
