def count_numbers_not_prime_powers(L, R):
    """Count numbers in [L, R] that are not prime powers"""

    # Count numbers that are not prime powers
    # A number is a prime power if it can be written as p^k where p is prime and k >= 1

    # Count numbers that are prime powers in [L, R]
    def count_prime_powers_up_to(n):
        if n < 2:
            return 0

        def segmented_sieve(n):
            sieve_limit = int(math.sqrt(n)) + 1
            sieve = [True] * (sieve_limit + 1)
            sieve[0] = sieve[1] = False
            for i in range(2, int(math.sqrt(sieve_limit)) + 1):
                if sieve[i]:
                    sieve[i*i : sieve_limit+1 : i] = [False] * len(sieve[i*i : sieve_limit+1 : i])

            result = 0

            segment_size = sieve_limit
            num_segments = (n - 1) // segment_size + 1

            for start in range(0, n, segment_size):
                end = min(n, start + segment_size)
                segment = [True] * (end - start + 1)

                for i in range(2, int(math.sqrt(end)) + 1):
                    if sieve[i]:
                        start_i = max(i*i, start + (i - start % i) % i)
                        segment[start_i - start : end - start + 1 : i] = [False] * len(segment[start_i - start : end - start + 1 : i])

                prime_power_count = 0
                for pos in range(len(segment)):
                    if segment[pos]:
                        val = start + pos
                        if val < sieve_limit:
                            prime_power_count += 1
                        else:
