def is_perfect_kth_power(n, k):
    """Check if n is a perfect k-th power"""
    if n == 1:
        return True  # 1^k = 1

    # Try dividing by small primes
    max_prime = int(n**0.5) + 1
    for p in range(2, max_prime + 1):
        if n % p == 0:
            exponent = 0
            while n % p == 0:
                exponent += 1
                n //= p
            if exponent % k != 0:
                return False

    if n > 1:  # remaining prime factor
        return False

    return True

