def binomial(n, k):
    """Calculate C(n, k)"""
    if k < 0 or k > n:
        return 0
    if k == 0 or k == n:
        return 1
    # Calculate C(n, k) = n*(n-1)*...*(n-k+1) / (k*(k-1)*...*1)
    if k > n - k:
        k = n - k
    result = 1
    for i in range(1, k + 1):
        result = result * (n - k + i) // i
    return result

n, k = map(int, input().split())
a = list(map(int, input().split()))

result = []
for i in range(n):
    # Position i+1 in 1-indexed
    # For k=0, coefficient of a[j] is 1 if j = i, else 0
    # For k>0, coefficient of a[j] is C(k + (i-j) - 1, k) if j <= i
    if k == 0:
        value = a[i]
    else:
        value = 0
        for j in range(i + 1):
            # Calculate C(k + (i-j) - 1, k)
            coeff = binomial(k + (i - j) - 1, k)
            value += a[j] * coeff
    result.append(str(value))

print(' '.join(result))
