def get_primes(n):
    """Generate all primes up to n using Sieve of Eratosthenes"""
    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False
    for i in range(2, int(n**0.5) + 1):
        if is_prime[i]:
            for j in range(i*i, n + 1, i):
                is_prime[j] = False
    primes = [i for i, prime in enumerate(is_prime) if prime]
    return primes


def get_multiples(n, primes):
    """Find all multiples of primes that are >= n"""
    multiples = set()
    for p in primes:
        if p >= n:
            break
        # Find smallest multiple of p >= n
        if n % p == 0:
            multiples.add(n)
        else:
            multiples.add(n + (p - n % p))
    return multiples


def solve(X2):
    primes = get_primes(X2)

    # Find all possible X1 values that could reach X2
    X1_candidates = set()
    for p in primes:
        if p >= X2:
            break
        # Find predecessors of X2 from prime p
        if X2 % p == 0:
            X1_candidates.add(X2)
        else:
            X1_candidates.add(X2 - p)

    # Now find all possible X0 values that could reach any X1
    min_X0 = float('inf')
    for X1 in X1_candidates:
