        X0_candidates = set()
        for p in primes:
            if p >= X1:
                break
            if X1 % p == 0:
                X0_candidates.add(X1)
            else:
                X0_candidates.add(X1 - p)

        # Find min X0 for this X1
        for X0 in X0_candidates:
            # Check if X0 is valid (>= 3 and there exists a prime path)
            if X0 >= 3:
                min_X0 = min(min_X0, X0)

