def get_primes(n):
    """Generate all primes up to n using Sieve of Eratosthenes"""
    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False
    for i in range(2, int(n**0.5) + 1):
        if is_prime[i]:
            for j in range(i*i, n + 1, i):
                is_prime[j] = False
    primes = [i for i, prime in enumerate(is_prime) if prime]
    return primes


def solve(X2):
    primes = get_primes(X2)

    # Find all possible X1 values that could reach X2
    X1_candidates = set()
    for p in primes:
        if p >= X2:
            break
        if X2 % p == 0:
            # p divides X2, so X1 could be X2
            X1_candidates.add(X2)
        else:
            # p doesn't divide X2, so X1 could be X2 - p
            X1_candidates.add(X2 - p)

    # Now find all possible X0 values that could reach any X1
    min_X0 = float('inf')
    for X1 in X1_candidates:
        # For X1, find all possible X0 values that could reach it
        X0_candidates = set()
        for p in primes:
            if p >= X1:
                break
            if X1 % p == 0:
                # p divides X1, so X0 could be X1
                X0_candidates.add(X1)
            else:
                # p doesn't divide X1, so X0 could be X1 - p
                X0_candidates.add(X1 - p)

        # Find min X0 for this X1
        for X0 in X0_candidates:
            if X0 >= 3:
                min_X0 = min(min_X0, X0)

    return min_X0

