import sys

def find_bridges(n, edges):
    adj = [[] for _ in range(n + 1)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    disc = [0] * (n + 1)
    low = [0] * (n + 1)
    visited = [False] * (n + 1)
    time = 1

    def dfs(u, parent):
        nonlocal time
        visited[u] = True
        disc[u] = low[u] = time
        time += 1

        for v in adj[u]:
            if v == parent:
                continue

            if not visited[v]:
                dfs(v, u)
                low[u] = min(low[u], low[v])
                # Check if (u, v) is a bridge
                if low[v] > disc[u]:
                    print(f"Bridge: {u}-{v}")
            else:
                # Back edge
                low[u] = min(low[u], disc[v])

    for i in range(1, n + 1):
        if not visited[i]:
            dfs(i, -1)

    # Count bridges
    bridges = 0
    for i in range(1, n + 1):
        for j in adj[i]:
            if i < j and low[j] > disc[i]:
                bridges += 1
    return bridges

if __name__ == "__main__":
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    it = iter(data)
    n = int(next(it))
    m = int(next(it))
    edges = []
    for _ in range(m):
        u = int(next(it))
        v = int(next(it))
        edges.append((u, v))

    result = find_bridges(n, edges)
    print(result)
