import sys

def solve():
    a = sys.stdin.readline().strip()
    n = len(a)

    # dp[i][j][k]: number of ways to transform a[i..j] into a string ending with digit k
    # where k can be 0-9, and 0 means no ending digit (empty string)
    dp = [[[[0] * 10 for _ in range(10)] for __ in range(n)] for ___ in range(n)]

    # Base case: single digits
    for i in range(n):
        dp[i][i][int(a[i])][int(a[i])] = 1

    # Fill DP table
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1

            # Try all ways to split the substring
            for k in range(i, j):
                # Combine results from left and right
                for left_last in range(10):
                    for left_count in range(10):
                        for right_first in range(10):
                            for right_count in range(10):
                                left_ways = dp[i][k][left_last][left_count]
                                right_ways = dp[k+1][j][right_first][right_count]

                                # If the left ends with a digit and the right starts with a digit
                                # and they sum to 9, we can merge them
                                if left_last + right_first == 9:
                                    new_digit = 9
                                    new_count = left_count + right_count + 1
                                    dp[i][j][new_digit][new_count] += left_ways * right_ways
                                else:
                                    # Just concatenate
                                    new_digit = right_first
                                    new_count = left_count + right_count
                                    dp[i][j][new_digit][new_count] += left_ways * right_ways

    # Find the maximum number of 9s
    max_nines = 0
    for last_digit in range(10):
        for count in range(10):
            max_nines = max(max_nines, dp[0][n-1][last_digit][count])

    # Count distinct ways to achieve max nines
    ways = 0
    for last_digit in range(10):
        for count in range(10):
            if count == max_nines:
                ways += dp[0][n-1][last_digit][count]

    print(ways)

if __name__ == "__main__":
    solve()
