def rank(p, n, fact):
    r = 0
    used = [False] * n
    for i in range(n):
        count = 0
        for j in range(n):
            if not used[j] and p[i] > j:
                count += 1
        r = (r + count * fact[n-i-1]) % fact[n]
        used[p[i]] = True
    return r

def unrank(target, n, fact):
    used = [False] * n
    perm = [0] * n
    for i in range(n):
        for j in range(n):
            if not used[j]:
                if target < fact[n-i-1]:
                    perm[i] = j
                    used[j] = True
                    target -= 0
                else:
                    target -= fact[n-i-1]
    return perm

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    p = list(map(int, data[1:n+1]))
