def rank(p, n):
    r = 0
    used = [False] * n
    for i in range(n):
        count = 0
        for j in range(n):
            if not used[j] and p[i] > j:
                count += 1
        r += count * math.factorial(n - i - 1)
        used[p[i]] = True
    return r

def unrank(target, n):
    used = [False] * n
    perm = [0] * n
    for i in range(n):
        for j in range(n):
            if not used[j]:
                cnt = math.factorial(n - i - 1)
                if target < cnt:
                    perm[i] = j
                    used[j] = True
                else:
                    target -= cnt
    return perm

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    p = list(map(int, data[1:n+1]))
    q = list(map(int, data[n+1:2*n+1]))

    r1 = rank(p, n)
    r2 = rank(q, n)

    target = (r1 + r2) % math.factorial(n)

