def can_reach_k(grid, n, m, k, start):
    """Check if we can cover all marked squares from start using only k-length moves without revisiting segments"""

    # Helper to convert (i, j) to index
    def idx(i, j):
        return i * m + j

    # Marked squares
    marked = set()
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 1:
                marked.add((i, j))

    # If start not marked, invalid
    if start not in marked:
        return False

    # Directions: up, down, left, right
    dirs = [(-k, 0), (k, 0), (0, -k), (0, k)]

    # BFS to find reachable squares
    from collections import deque

    visited = set()
    visited.add(start)
    queue = deque([start])

    while queue:
        i, j = queue.popleft()

        # Try all directions
        for di, dj in dirs:
            ni, nj = i + di, j + dj

            # Check bounds and if (ni, nj) is marked
            if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] == 1:
                if (ni, nj) not in visited:
                    visited.add((ni, nj))
                    queue.append((ni, nj))

    # Check if all marked squares are reachable
    return len(visited) == len(marked)


