import sys
from collections import defaultdict

def number_to_pattern(number):
    """Convert a number to its parity pattern (18 digits, right to left)"""
    pattern = []
    digits = list(number)[::-1]  # Reverse for right-to-left processing

    for i, ch in enumerate(digits):
        if i >= 18:
            break  # Maximum length is 18 digits
        digit = int(ch)
        parity = '1' if digit % 2 == 1 else '0'
        pattern.append(parity)

    # Pad with 0s on the left if needed
    while len(pattern) < 18:
        pattern.append('0')

    return ''.join(pattern)

def pattern_to_query(pattern):
    """Convert query pattern to full 18-digit pattern"""
    # Pad with 0s on the left if needed
    while len(pattern) < 18:
        pattern = '0' + pattern
    return pattern

t = int(sys.stdin.readline())
pattern_counts = defaultdict(int)

for _ in range(t):
    line = sys.stdin.readline().split()

    if line[0] == '+':
        number = line[1]
        pattern = number_to_pattern(number)
        pattern_counts[pattern] += 1

    elif line[0] == '-':
        number = line[1]
        pattern = number_to_pattern(number)
        pattern_counts[pattern] -= 1

    elif line[0] == '?':
        query_pattern = line[1]
        full_pattern = pattern_to_query(query_pattern)
        print(pattern_counts.get(full_pattern, 0))
