                # Disappointed: this dish is definitely out of stock
                available[tj - 1] = False

                # This dish was used up (at least by this passenger)
                if used[tj - 1] < a[tj - 1]:
                    used[tj - 1] += 1
            else:
                # Not disappointed: got exactly what they asked for
                if used[tj - 1] < a[tj - 1]:
                    used[tj - 1] += 1

        # Build answer string
        res = []
        for i in range(k):
            if not available[i] or used[i] == a[i]:
                res.append('Y')
            else:
                res.append('N')

        print(''.join(res))

