for r in range(n):
    for c in range(n):
        x, y = target[r][c]

        # Check if it's a blocked zone
        if x == -1 and y == -1:
            grid[r][c] = 'X'
        else:
            # Check which instruction leads to (x, y)
            if r > 0 and (r-1, c) == (x-1, y-1):
                grid[r][c] = 'U'
            elif r < n-1 and (r+1, c) == (x-1, y-1):
                grid[r][c] = 'D'
            elif c > 0 and (r, c-1) == (x-1, y-1):
                grid[r][c] = 'L'
            elif c < n-1 and (r, c+1) == (x-1, y-1):
                grid[r][c] = 'R'
            else:
                # No valid instruction found
                print("INVALID")
                exit()

# Verify the solution
def verify(grid, target, n):
    for r in range(n):
        for c in range(n):
            x, y = target[r][c]
            if x == -1 and y == -1:
                # Should be X
                if grid[r][c] != 'X':
                    return False
            else:
                # Move according to instruction
                if grid[r][c] == 'U':
                    nr, nc = r-1, c
                elif grid[r][c] == 'D':
                    nr, nc = r+1, c
                elif grid[r][c] == 'L':
                    nr, nc = r, c-1
                elif grid[r][c] == 'R':
                    nr, nc = r, c+1
                else:  # X
                    nr, nc = r, c

                # Check if this leads to the target
                if (nr, nc) != (x-1, y-1):
                    return False
    return True

if verify(grid, target, n):
    print("VALID")
    for row in grid:
        print(''.join(row))
else:
    print("INVALID")
