    n = int(next(it))
    bombs = [(int(next(it)), int(next(it))) for _ in range(n)]

    operations = []

    # For each bomb, we'll add the operations to the list
    for (x, y) in bombs:
        # Move to the bomb in two steps
        if x > 0:
            operations.append(f"1 {x} R")
        elif x < 0:
            operations.append(f"1 {-x} L")
        if y > 0:
            operations.append(f"1 {y} U")
        elif y < 0:
            operations.append(f"1 {-y} D")

        # Pick up the bomb
        operations.append("2")

        # Move back from the bomb
        if x > 0:
            operations.append(f"1 {x} L")
        elif x < 0:
            operations.append(f"1 {-x} R")
        if y > 0:
            operations.append(f"1 {y} D")
        elif y < 0:
            operations.append(f"1 {-y} U")

        # Destroy the bomb
        operations.append("3")

