{"code": "
import sys
import bisect

def is_lucky(n):
    """Check if a number is lucky (only contains digits 4 and 7)"""
    s = str(n)
    return all(c in '47' for c in s)

def generate_lucky_numbers(limit):
    """Generate all lucky numbers up to limit"""
    lucky = []
    from itertools import product
    for length in range(1, len(str(limit)) + 1):
        for digits in product(['4', '7'], repeat=length):
            num = int(''.join(digits))
            if num <= limit:
                lucky.append(num)
    return sorted(lucky)

def count_lucky_numbers(n, lucky):
    """Count lucky numbers ≤ n"""
    return bisect.bisect_right(lucky, n)

# Read input
pl, pr, vl, vr, k = map(int, sys.stdin.read().split())

# Generate all lucky numbers up to max possible value
lucky_numbers = generate_lucky_numbers(10**9)

# Count total pairs
total_pairs = (pr - pl + 1) * (vr - vl + 1)

# Count valid pairs using brute force (for small ranges)
valid_pairs = 0

for p in range(pl, pr + 1):
    for v in range(vl, vr + 1):
        a = min(p, v)
        b = max(p, v)
        lucky_count = count_lucky_numbers(b, lucky_numbers) - count_lucky_numbers(a - 1, lucky_numbers)
        if lucky_count == k:
            valid_pairs += 1

probability = valid_pairs / total_pairs
print(probability)
"}

