    # We'll count the number of ways to reduce the number to the maximum number of 9s

    # DP state: dp[i][j] = number of ways to reduce substring a[i..j]
    # to a single digit, preserving the order of digits
    dp = [[0] * n for _ in range(n)]

    # Base case: single digit
    for i in range(n):
        dp[i][i] = 1

    # Fill DP table
    for length in range(2, n + 1):  # length of substring
        for i in range(n - length + 1):
