def to_base_k(n, k):
    """Convert a number to base k, using letters for values >= 10."""
    digits = []
    while n > 0:
        remainder = n % k
        if remainder < 10:
            digits.append(str(remainder))
        else:
            digits.append(chr(ord('A') + remainder - 10))
        n //= k
    return ''.join(reversed(digits))

for i in range(1, k):
    row = []
    for j in range(1, k):
        product = i * j
        row.append(to_base_k(product, k))
    print('  '.join(row))
