    n, m = map(int, input().split())
    graph = [[] for _ in range(n + 1)]
    edges = []

    for _ in range(m):
        x, y = map(int, input().split())
        graph[x].append(y)
        graph[y].append(x)
        edges.append((x, y))

    # Greedy algorithm to find maximum edge cut
    # Start with A = {1}
    A = set([1])

    for _ in range(n - 1):
        # Find the vertex not in A with the most edges to A
        max_edges = -1
        best_vertex = -1

        for vertex in range(1, n + 1):
            if vertex in A:
                continue

            count = 0
            for neighbor in graph[vertex]:
                if neighbor in A:
                    count += 1

            if count > max_edges:
                max_edges = count
                best_vertex = vertex

        if best_vertex == -1:
            break

        A.add(best_vertex)

    # Count edges between A and its complement
    edge_count = 0

    for x, y in edges:
        if (x in A and y not in A) or (y in A and x not in A):
            edge_count += 1

    print(edge_count)

