def max_bosses():
    n, m = map(int, input().split())
    graph = [[] for _ in range(n + 1)]
    edges = []

    for _ in range(m):
        x, y = map(int, input().split())
        graph[x].append(y)
        graph[y].append(x)
        edges.append((x, y))

    max_bosses = 0

    # Brute force for small n (this won't work for large n, but let's debug)
    if n <= 10:
        # Try all pairs (s, t) where s < t
        for s in range(1, n + 1):
            for t in range(1, n + 1):
                if s == t:
                    continue

                # Find all critical edges for s to t
                critical_edges = set()

                for edge in edges:
                    x, y = edge

                    # Check if edge (x, y) is critical
                    # Create a copy of the graph without this edge
                    temp_graph = [[] for _ in range(n + 1)]
                    for nx, ny in edges:
                        if nx == x and ny == y:
                            continue
                        temp_graph[nx].append(ny)
                        temp_graph[ny].append(nx)

                    # Check if s and t are still connected
                    visited = set([s])
                    stack = [s]

                    while stack:
                        node = stack.pop()
                        for neighbor in temp_graph[node]:
                            if neighbor not in visited:
                                visited.add(neighbor)
                                stack.append(neighbor)

                    if t not in visited:
                        critical_edges.add((x, y))

                max_bosses = max(max_bosses, len(critical_edges))

    print(max_bosses)

max_bosses()
