def solve():
    n = int(input())

    # Build adjacency list
    tree = [[] for _ in range(n)]
    for _ in range(n - 1):
        u, v = map(int, input().split())
        tree[u - 1].append(v - 1)
        tree[v - 1].append(u - 1)

    # The answer for this problem is n * (n + 1) / 2 - sum over all vertices v of size[v] * (size[v] + 1) / 2
    # Let me calculate the size of each subtree

    def dfs_size(u, parent):
        size = 1
        for v in tree[u]:
            if v != parent:
                size += dfs_size(v, u)
        return size

    def dfs_sum(u, parent):
        size = dfs_size(u, parent)

        # Sum of sizes of all subtrees rooted at u
        sum_sizes = 0
        for v in tree[u]:
            if v != parent:
                sum_sizes += dfs_size(v, u)

        return size * (size + 1) // 2 + sum_sizes

    total = dfs_sum(0, None)
    print(total)

