import sys

def solve(p, k):
    coefficients = []
    r = p

    while r > 0:
        a_i = r % k
        coefficients.append(a_i)
        r = (r + a_i) // k

    # If r is not zero after the loop, then it's impossible
    if r != 0:
        return -1

    # Reverse coefficients to get correct order
    coefficients.reverse()

    return coefficients

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    p = int(data[0])
    k = int(data[1])

    coefficients = solve(p, k)

    if coefficients == -1:
        print(-1)
    else:
        print(len(coefficients))
        print(' '.join(map(str, coefficients)))

if __name__ == '__main__':
    main()
