def is_prime(num):
    if num < 2:
        return False
    for i in range(2, int(num**0.5)+1):
        if num % i == 0:
            return False
    return True

n = int(input())
a = list(map(int, input().split()))
operations = []

for i in range(1, n+1):
    if a[i-1] == i:
        continue

    # Find where element i is located
    j = a.index(i) + 1  # position j where element i is located

    # If we need to move element i to position i
    # First, check if we can go directly from j to i
    if is_prime(j - i + 1):
        operations.append((i, j))
        a[i-1], a[j-1] = a[j-1], a[i-1]
    else:
        # Use position 1 as an intermediary
        # First go from j to 1
