import sys

def count_with_k_ones(x, k):
    """Count numbers from 0 to x (inclusive) with exactly k ones in binary representation."""
    if k < 0 or k > x.bit_length():
        return 0
    # Binary search to find the count
    result = 0
    bit = x.bit_length()

    def count_less_or_equal(mask):
        bits = 0
        n = mask
        while n:
            if n & 1:
                bits += 1
            n >>= 1
        if bits != k:
            return 0

        cnt = 0
        for i in range(1, bit + 1):
            cnt += i
        return cnt

    i = 0
    n = x
    while n:
        if n & 1:
            i += 1
        n >>= 1
        result += count_less_or_equal(n)

    return result

def main():
    m, k = map(int, sys.stdin.read().split())

    # Binary search for n in [1, 10^18]
    low, high = 1, 10**18
    answer = 1

    while low <= high:
        mid = (low + high) // 2
        # Count numbers with exactly k ones in [mid+1, 2*mid]
        cnt = count_with_k_ones(2 * mid, k) - count_with_k_ones(mid, k)
        if cnt == m:
            answer = mid
            high = mid - 1
        elif cnt < m:
            low = mid + 1
        else:
            high = mid - 1

    print(answer)

if __name__ == "__main__":
    main()
