def calculate_value(a, n):
    size = 1 << n
    tree = [0] * size

    # Fill leaves with the original array
    for i in range(size):
        tree[i] = a[i]

    # Build upper levels
    for level in range(1, n+1):
        if level % 2 == 1:
            # OR operation
            for i in range(size // 2):
                tree[i] = tree[2*i] | tree[2*i + 1]
        else:
            # XOR operation
            for i in range(size // 2):
                tree[i] = tree[2*i] ^ tree[2*i + 1]
        size //= 2

    return tree[0]

def solve():
    import sys
    data = sys.stdin.read().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    m = int(next(it))
    a = [int(next(it)) for _ in range(2*n)]

    for _ in range(m):
        pi = int(next(it)) - 1
        bi = int(next(it))
        a[pi] = bi

        result = calculate_value(a, n)
        print(result)

solve()
